#include "game/world12/inactive_national_draw_codec.hpp"
#include "formats/binary.hpp"
#include <algorithm>
#include <utility>
namespace bmh::world12 {
namespace {using J=cli::Json;const J& field(const J& j,const char* name){if(!j.object())throw FormatError("world12: inactive national object expected");const auto at=j.object()->find(name);if(at==j.object()->end())throw FormatError("world12: inactive national receipt field missing");return at->second;}uint32_t number(const J& j,uint32_t max){const auto n=j.integer();if(!n||*n<0||uint64_t(*n)>max)throw FormatError("world12: inactive national raw word out of range");return uint32_t(*n);}}
cli::Json encode_inactive_national_draw(const std::optional<InactiveNationalDraw>& input){if(!input)return nullptr;const auto& c=*input;const auto words=[](const auto& values){J::Array out;for(auto n:values)out.emplace_back(int(n));return out;};return J::Object{{"season",int(c.season)},{"native_national_first",int(c.native_national_first)},{"native_first_small",int(c.native_first_small)},{"field_tokens",words(c.field_tokens)},{"four_seed_tokens",words(c.four_seed_tokens)},{"six_seed_tokens",words(c.six_seed_tokens)}};}
std::optional<InactiveNationalDraw> decode_inactive_national_draw(const cli::Json& input){if(std::holds_alternative<std::nullptr_t>(input.value))return {};InactiveNationalDraw c;c.season=number(field(input,"season"),32767);c.native_national_first=uint16_t(number(field(input,"native_national_first"),65535));c.native_first_small=uint16_t(number(field(input,"native_first_small"),65535));const auto words=[&](const char* name){const auto value=field(input,name).array();if(!value||value->size()>24)throw FormatError("world12: inactive national raw array invalid");std::vector<uint16_t> out;for(const auto& n:*value)out.push_back(uint16_t(number(n,65535)));return out;};c.field_tokens=words("field_tokens");for(const auto& [name,target]:{std::pair{"four_seed_tokens",&c.four_seed_tokens},std::pair{"six_seed_tokens",&c.six_seed_tokens}}){const auto values=words(name);if(values.size()!=2)throw FormatError("world12: inactive national seed pair invalid");std::copy(values.begin(),values.end(),target->begin());}return c;}
}
